    KEY_FOLD_BLOCK(aEarthLaneC, 13U, 215U, aCrystalLaneD, 34U, 216U, aLargeA, 0U);
    KEY_FOLD_BLOCK(aCrystalLaneA, 1U, 336U, aEarthLaneB, 8U, 138U, aLargeA, 1U);
